∃ (k : ℕ) (C : PEqualNP.CircuitLowerBounds.Circuit),
  let N := 2^k
  let bits := fun (v : Fin N) => (Finset.univ : Finset (Fin k)).filter (fun i => v.val.testBit i.val)
  let G := fun (u j : Fin N) => ((bits u ∩ bits j).card % 2 == 1)
  6 ≤ k ∧ PEqualNP.MetaComplexity.FanInTwo C ∧ PEqualNP.Represents.Represents G C ∧
    4*C.size ≤ 9*N
